INSERT INTO article (id, title, content, author_id, likes_count, comments_count, log_score, created_at, updated_at)
VALUES
    (gen_random_uuid(), 'Введение в программирование: с чего начать?', 'Программирование — это процесс создания компьютерных программ. Для начинающих лучше всего подойдут языки Python или JavaScript. В этой статье рассмотрим основные концепции: переменные, циклы, условия и функции. Также разберём типичные ошибки новичков и способы их решения. Программирование открывает множество возможностей для карьерного роста и творчества.', '34f86578-c009-4282-bcf6-299c3890daec', 45, 12, 4.8, now(), now()),
    (gen_random_uuid(), '10 лучших практик написания чистого кода', 'Чистый код — это код, который легко читать, понимать и поддерживать. В этой статье собраны главные принципы: осмысленные имена переменных, маленькие функции, отсутствие дублирования, правильная обработка ошибок, комментирование только сложной логики, соблюдение стандартов форматирования, использование автоматических тестов, рефакторинг, следование принципам SOLID и регулярные код-ревью.', '34f86578-c009-4282-bcf6-299c3890daec', 128, 34, 4.9, now(), now()),
    (gen_random_uuid(), 'Что такое Docker и зачем он нужен?', 'Docker — это платформа для контейнеризации приложений. Контейнеры позволяют упаковать приложение со всеми зависимостями в изолированную среду. Это решает проблему «на моём компьютере работает». Docker упрощает развёртывание, масштабирование и управление приложениями. В статье объясняются основные понятия: образы, контейнеры, Dockerfile, docker-compose, реестры образов и отличия от виртуальных машин.', '34f86578-c009-4282-bcf6-299c3890daec', 89, 23, 4.7, now(), now()),
    (gen_random_uuid(), 'Основы SQL: SELECT, INSERT, UPDATE, DELETE', 'SQL — язык структурированных запросов для работы с базами данных. SELECT используется для выборки данных, INSERT — для добавления новых записей, UPDATE — для обновления существующих, DELETE — для удаления. В статье приведены примеры каждого типа запросов, объяснены WHERE, ORDER BY, GROUP BY, JOIN, а также даны советы по оптимизации запросов и избеганию типичных ошибок.', '34f86578-c009-4282-bcf6-299c3890daec', 234, 67, 4.9, now(), now()),
    (gen_random_uuid(), 'Git: система контроля версий для начинающих', 'Git — это распределённая система контроля версий, которая позволяет отслеживать изменения в коде. Основные команды: git init, git add, git commit, git push, git pull, git branch, git merge. В статье объясняется, как работает Git, что такое коммиты, ветки, удалённые репозитории, как разрешать конфликты. Также рассмотрены лучшие практики работы с Git в команде и популярные платформы (GitHub, GitLab, Bitbucket).', '34f86578-c009-4282-bcf6-299c3890daec', 312, 89, 4.9, now(), now()),
    (gen_random_uuid(), 'REST API: принципы и примеры использования', 'REST (Representational State Transfer) — архитектурный стиль для построения веб-API. Основные принципы: клиент-сервер, отсутствие состояния, кеширование, единообразие интерфейса (CRUD операции через HTTP методы: GET, POST, PUT, DELETE), слоированная система, код по требованию. В статье приведены примеры REST API запросов, объяснены статус-коды HTTP, форматы данных JSON/XML, а также даны советы по проектированию удобного API.', '34f86578-c009-4282-bcf6-299c3890daec', 167, 45, 4.8, now(), now()),
    (gen_random_uuid(), 'Микросервисная архитектура: плюсы и минусы', 'Микросервисы — это подход, при котором приложение разбивается на множество маленьких независимых сервисов. Плюсы: независимое развёртывание, масштабирование, технологии могут отличаться, устойчивость к отказам. Минусы: сложность управления, сетевое взаимодействие, распределённые транзакции, сложность тестирования и отладки. Статья поможет понять, когда стоит использовать микросервисы, а когда лучше оставаться в рамках монолита.', '34f86578-c009-4282-bcf6-299c3890daec', 98, 31, 4.6, now(), now()),
    (gen_random_uuid(), 'Базы данных: нормализация и денормализация', 'Нормализация — процесс устранения избыточности данных путём разделения таблиц. Существуют нормальные формы: 1НФ, 2НФ, 3НФ, НФБК и т.д. Денормализация — обратный процесс, добавление избыточности для ускорения чтения. В статье на примерах показаны различия, рассмотрены компромиссы между скоростью записи и чтения, а также когда какой подход предпочтительнее.', '34f86578-c009-4282-bcf6-299c3890daec', 76, 18, 4.7, now(), now()),
    (gen_random_uuid(), 'Асинхронное программирование в Python', 'Асинхронное программирование позволяет выполнять несколько операций параллельно без блокировки основного потока. В Python для этого используются ключевые слова async/await, библиотеки asyncio, aiohttp. Статья объясняет разницу между синхронным, многопоточным и асинхронным кодом, показывает примеры, рассматривает event loop, корутины, задачи, а также типичные ошибки при работе с асинхронностью.', '34f86578-c009-4282-bcf6-299c3890daec', 145, 42, 4.8, now(), now()),
    (gen_random_uuid(), 'CI/CD: непрерывная интеграция и доставка', 'CI/CD — это практики автоматизации процесса разработки. CI (Continuous Integration) — автоматическая сборка и тестирование при каждом пуше в репозиторий. CD (Continuous Delivery/Deployment) — автоматическое развёртывание на тестовых/боевых серверах. В статье рассмотрены инструменты (GitHub Actions, GitLab CI, Jenkins, TeamCity), примеры конфигураций, лучшие практики и преимущества внедрения.', '34f86578-c009-4282-bcf6-299c3890daec', 112, 29, 4.8, now(), now()),
    (gen_random_uuid(), 'TypeScript vs JavaScript: что выбрать?', 'TypeScript — это надмножество JavaScript, добавляющее статическую типизацию. Плюсы TypeScript: раннее обнаружение ошибок, лучшая поддержка IDE, удобный рефакторинг, современные возможности ES6+. Минусы: необходимость компиляции, сложнее для начинающих. Статья поможет сделать выбор в зависимости от проекта, команды и требований к надёжности кода.', '34f86578-c009-4282-bcf6-299c3890daec', 203, 58, 4.8, now(), now()),
    (gen_random_uuid(), 'Структуры данных: массивы, списки, словари', 'Структуры данных — это способ организации и хранения данных. Массивы: фиксированный размер, быстрый доступ по индексу. Списки: динамический размер, медленный поиск. Словари (хэш-таблицы): быстрый поиск по ключу. В статье на примерах Python показаны особенности каждой структуры, временная сложность операций (Big O notation) и ситуации, когда какую структуру лучше использовать.', '34f86578-c009-4282-bcf6-299c3890daec', 89, 27, 4.7, now(), now()),
    (gen_random_uuid(), 'Алгоритмы сортировки: сравнение и реализация', 'Алгоритмы сортировки — основа программирования. Рассмотрены: пузырьковая сортировка (O(n²)), быстрая сортировка (O(n log n) в среднем), сортировка слиянием (O(n log n)), сортировка вставками (эффективна для почти отсортированных данных). Статья содержит реализации на Python, сравнение производительности на разных объёмах данных и рекомендации по выбору алгоритма.', '34f86578-c009-4282-bcf6-299c3890daec', 134, 41, 4.8, now(), now()),
    (gen_random_uuid(), 'React для начинающих: компоненты и состояние', 'React — библиотека для построения пользовательских интерфейсов. Основные концепции: компоненты (функциональные и классовые), JSX, состояние (state), пропсы (props), хуки (useState, useEffect, useContext). В статье разбирается создание первого приложения, управление состоянием, обработка событий, условный рендеринг и рендеринг списков. Также приведены примеры кода.', '34f86578-c009-4282-bcf6-299c3890daec', 267, 73, 4.9, now(), now()),
    (gen_random_uuid(), 'Безопасность веб-приложений: основные угрозы', 'OWASP Top 10 — список основных угроз веб-безопасности. Статья объясняет каждую: инъекции (SQL, NoSQL, LDAP), нарушение аутентификации, XSS (межсайтовый скриптинг), CSRF (межсайтовая подделка запроса), небезопасная десериализация, использование компонентов с уязвимостями. Даются практические советы по защите и примеры уязвимого кода с исправлениями.', '34f86578-c009-4282-bcf6-299c3890daec', 178, 52, 4.8, now(), now()),
    (gen_random_uuid(), 'Kubernetes: оркестрация контейнеров', 'Kubernetes (K8s) — система для автоматизации развёртывания, масштабирования и управления контейнерными приложениями. Основные понятия: Pod, Service, Deployment, Ingress, ConfigMap, Secret, Namespace. Статья объясняет архитектуру K8s (master node, worker nodes, etcd, kube-apiserver), как деплоить приложения, настроить горизонтальное масштабирование и обновления без даунтайма.', '34f86578-c009-4282-bcf6-299c3890daec', 156, 38, 4.7, now(), now()),
    (gen_random_uuid(), 'Регулярные выражения: полное руководство', 'Регулярные выражения (regex) — мощный инструмент для поиска и замены текста по шаблону. Статья охватывает: основные метасимволы (., *, +, ?, ^, $), классы символов (\\d, \\w, \\s), квантификаторы, группировку (группы), lookahead/lookbehind. Приведены примеры для валидации email, телефонов, URL, извлечения данных из текста на Python с библиотекой re.', '34f86578-c009-4282-bcf6-299c3890daec', 95, 26, 4.6, now(), now()),
    (gen_random_uuid(), 'GraphQL: альтернатива REST API', 'GraphQL — язык запросов и среда выполнения для API, разработанный Facebook. В отличие от REST, клиент сам определяет, какие поля нужны. Статья объясняет: схема (Schema), типы (Query, Mutation, Subscription), резолверы. Приводятся примеры запросов, сравнение с REST (пере- и недо-выборка данных, версионирование), а также библиотеки для реализации (Apollo, GraphQL Yoga).', '34f86578-c009-4282-bcf6-299c3890daec', 87, 21, 4.7, now(), now()),
    (gen_random_uuid(), 'Оптимизация производительности SQL запросов', 'Медленные запросы — частая проблема. Статья даёт практические советы: создание индексов (B-tree, hash, полнотекстовые), анализ плана запроса с EXPLAIN, избегание SELECT *, правильное использование JOIN, подзапросов, оконных функций. Также рассмотрены анти-паттерны (N+1 проблема, запросы в цикле) и инструменты мониторинга (pg_stat_statements, slow query log).', '34f86578-c009-4282-bcf6-299c3890daec', 201, 63, 4.8, now(), now()),
    (gen_random_uuid(), 'Django: создание веб-приложения за час', 'Django — высокоуровневый фреймворк для веб-разработки на Python. Статья по шагам описывает: установку, создание проекта и приложения, настройку моделей, миграции, административную панель, маршрутизацию (urls), шаблоны (templates), формы, аутентификацию. Результат — работающий блог или список задач. Также даны ссылки на документацию и лучшие практики.', '34f86578-c009-4282-bcf6-299c3890daec', 345, 98, 4.9, now(), now()),
    (gen_random_uuid(), 'NoSQL базы данных: MongoDB, Cassandra, Redis', 'NoSQL — базы данных, не использующие реляционную модель. MongoDB — документо-ориентированная (JSON-подобные документы). Cassandra — колоночная, горизонтально масштабируется, высокая доступность. Redis — In-memory, ключ-значение, для кеширования и очередей. Статья сравнивает с реляционными БД, объясняет CAP-теорему, приводит примеры запросов и сценарии использования.', '34f86578-c009-4282-bcf6-299c3890daec', 123, 34, 4.7, now(), now()),
    (gen_random_uuid(), 'Принципы SOLID в объектно-ориентированном программировании', 'SOLID — пять принципов для создания поддерживаемого кода: S (Single Responsibility) — один класс отвечает за одну задачу, O (Open-Closed) — открыт для расширения, закрыт для изменения, L (Liskov Substitution) — подтипы заменяют базовые типы, I (Interface Segregation) — клиент не зависит от неиспользуемых методов, D (Dependency Inversion) — зависимость от абстракций. Примеры на Java/Python.', '34f86578-c009-4282-bcf6-299c3890daec', 289, 82, 4.9, now(), now()),
    (gen_random_uuid(), 'WebSocket: двусторонняя связь в реальном времени', 'WebSocket — протокол, обеспечивающий постоянное соединение между клиентом и сервером для обмена сообщениями в реальном времени. В отличие от HTTP, инициатором сообщения может выступать любая сторона. Статья объясняет, как работает handshake, библиотеки (Socket.IO на JS, websockets/WebSocket на Python), пример чата, онлайн-игры, трансляции котировок.', '34f86578-c009-4282-bcf6-299c3890daec', 76, 19, 4.6, now(), now()),
    (gen_random_uuid(), 'JWT: JSON Web Tokens для аутентификации', 'JWT — компактный и самодостаточный способ передачи данных между сторонами. Состоит из заголовка, полезной нагрузки и подписи. Используется для авторизации в API и SSO (Single Sign-On). Статья объясняет структуру токена, алгоритмы подписи (HS256, RS256), отличие от сессий, как хранить токены на клиенте (HttpOnly cookies, localStorage), как делать refresh токены.', '34f86578-c009-4282-bcf6-299c3890daec', 198, 56, 4.8, now(), now()),
    (gen_random_uuid(), 'Декораторы в Python: понимание и использование', 'Декораторы — функции, которые принимают другую функцию и расширяют её поведение. Статья на примерах объясняет: функции высшего порядка, замыкания, синтаксис @decorator, декораторы с аргументами, сохранение метаданных (functools.wraps). Реальные примеры: логирование, измерение времени выполнения, кеширование (lru_cache), проверка прав доступа, повторные попытки.', '34f86578-c009-4282-bcf6-299c3890daec', 167, 48, 4.8, now(), now()),
    (gen_random_uuid(), 'Кэширование: стратегии и инструменты (Redis, Memcached)', 'Кэширование — временное хранение данных для ускорения доступа. Стратегии: cache-aside (ленивая загрузка), write-through (сквозная запись), write-behind (отложенная запись), refresh-ahead. Статья сравнивает Redis (расширенные структуры данных, персистентность) и Memcached (простой, многопоточный). Приводятся примеры кэширования запросов к БД, HTML фрагментов, API ответов.', '34f86578-c009-4282-bcf6-299c3890daec', 142, 37, 4.7, now(), now()),
    (gen_random_uuid(), 'Тестирование кода: unit, интеграционное, e2e', 'Тестирование — неотъемлемая часть разработки. Unit тесты проверяют отдельные компоненты (JUnit, PyTest). Интеграционные — взаимодействие модулей (базы данных, API). E2E — пользовательские сценарии (Selenium, Cypress). Статья объясняет TDD (Test-Driven Development), моки (mock, stub, spy), покрытие кода тестами, пирамиду тестирования, автоматизацию в CI/CD.', '34f86578-c009-4282-bcf6-299c3890daec', 189, 53, 4.8, now(), now()),
    (gen_random_uuid(), 'Алгоритмы поиска: бинарный поиск, поиск в глубину/ширину', 'Статья объясняет основные алгоритмы поиска: бинарный поиск (O(log n) для отсортированного массива), поиск в глубину (DFS — стек/рекурсия), поиск в ширину (BFS — очередь) для графов и деревьев. Приводятся реализации на Python, анализ временной и пространственной сложности, примеры применения (поиск пути, обход дерева, поиск элемента).', '34f86578-c009-4282-bcf6-299c3890daec', 108, 31, 4.7, now(), now()),
    (gen_random_uuid(), 'Функциональное программирование: map, filter, reduce', 'Функциональное программирование — парадигма, где вычисления строятся на применении функций к данным. Статья на примерах Python объясняет чистые функции, неизменяемость данных, функции высшего порядка: map (применение к каждому элементу), filter (фильтрация), reduce (свёртка). Также рассматриваются lambda-функции, list comprehensions и их преимущества в читаемости.', '34f86578-c009-4282-bcf6-299c3890daec', 93, 24, 4.6, now(), now()),
    (gen_random_uuid(), 'Кроссплатформенная разработка: Flutter, React Native, Kotlin Multiplatform', 'Фреймворки для создания приложений под iOS и Android из одного кода. Flutter (Dart) — собственный движок рендеринга. React Native (JavaScript/TypeScript) — нативный рендеринг через мост. Kotlin Multiplatform — компиляция в нативный код для каждой платформы. Статья сравнивает производительность, скорость разработки, экосистему, порог входа.', '34f86578-c009-4282-bcf6-299c3890daec', 156, 44, 4.7, now(), now()),
    (gen_random_uuid(), 'Дизайн-паттерны: Singleton, Factory, Observer', 'Паттерны проектирования — типовые решения частых проблем. Singleton (одиночка) — гарантирует единственный экземпляр класса. Factory (фабрика) — делегирует создание объектов подклассам. Observer (наблюдатель) — оповещает зависимые объекты об изменениях. Статья приводит реализацию на Python/Java, примеры использования (логгеры, UI события, конфигурации).', '34f86578-c009-4282-bcf6-299c3890daec', 234, 67, 4.9, now(), now()),
    (gen_random_uuid(), 'Docker Compose: оркестрация нескольких контейнеров', 'Docker Compose — инструмент для запуска многоконтейнерных приложений. Статья объясняет файл docker-compose.yml (services, networks, volumes, environment), базовые команды (up, down, logs, exec). Пример типичного стека: веб-приложение (Python/Node), база данных (PostgreSQL), кеш (Redis), прокси (Nginx). Также про управление окружениями (dev/stage/prod).', '34f86578-c009-4282-bcf6-299c3890daec', 87, 22, 4.6, now(), now()),
    (gen_random_uuid(), 'RabbitMQ и брокеры сообщений для асинхронных задач', 'Брокеры сообщений (message brokers) нужны для асинхронной обработки, разгрузки API, обмена данными между сервисами. Статья объясняет очередь (queue), обменник (exchange), привязку (binding), producer/consumer. Рассматриваются топологии (direct, topic, fanout), пример на Python (aio-pika). Альтернативы: RabbitMQ, Apache Kafka, Redis Pub/Sub.', '34f86578-c009-4282-bcf6-299c3890daec', 112, 29, 4.7, now(), now()),
    (gen_random_uuid(), 'Java vs Python: сравнение языков программирования', 'Java и Python — два популярных языка. Статья сравнивает: синтаксис (статическая vs динамическая типизация), производительность (JIT vs интерпретатор), экосистему (библиотеки, фреймворки), порог входа, сценарии использования (корпоративная разработка, бэкенд, data science, автоматизация), управление памятью (GC), многопоточность.', '34f86578-c009-4282-bcf6-299c3890daec', 345, 101, 4.8, now(), now()),
    (gen_random_uuid(), 'Продвинутый SQL: оконные функции и CTE', 'Оконные функции (ROW_NUMBER, RANK, LAG, LEAD, SUM OVER) позволяют выполнять расчёты по группам строк без группировки. CTE (Common Table Expressions) с WITH — временные именованные подзапросы для улучшения читаемости. Статья содержит реальные примеры: пагинация, сравнение с предыдущим периодом, кумулятивные суммы, рекурсивные CTE для работы с деревьями.', '34f86578-c009-4282-bcf6-299c3890daec', 178, 51, 4.8, now(), now()),
    (gen_random_uuid(), 'CI/CD с GitHub Actions: практическое руководство', 'GitHub Actions — встроенная CI/CD платформа. Статья пошагово создаёт workflow: события (push, pull_request), джобы (jobs), шаги (steps), экшены (actions/checkout, actions/setup-python), матричные сборки, кеширование зависимостей, деплой на сервер (SSH) или в облака (AWS, Azure). Пример: тестирование и публикация Docker образа.', '34f86578-c009-4282-bcf6-299c3890daec', 145, 39, 4.7, now(), now()),
    (gen_random_uuid(), 'gRPC: высокопроизводительный RPC фреймворк', 'gRPC — фреймворк от Google для вызова удалённых процедур с использованием Protocol Buffers. Статья объясняет: .proto файлы (определение сервиса и сообщений), HTTP/2 (мультиплексирование, потоковая передача), коды состояния, поддержка 10+ языков. Сравнение с REST (скорость, контракт, строгая типизация). Пример на Python: сервер и клиент.', '34f86578-c009-4282-bcf6-299c3890daec', 98, 24, 4.6, now(), now()),
    (gen_random_uuid(), 'Event-Driven Architecture: события вместо прямых вызовов', 'Событийно-ориентированная архитектура: компоненты взаимодействуют через события (messages, events). Плюсы: слабая связанность, масштабируемость, асинхронность. Минусы: сложность отладки, eventual consistency. Статья объясняет event bus, event sourcing, CQRS (Command Query Responsibility Segregation). Примеры: онлайн-заказы, уведомления, логирование.', '34f86578-c009-4282-bcf6-299c3890daec', 123, 32, 4.7, now(), now()),
    (gen_random_uuid(), 'Swagger/OpenAPI: документация и тестирование API', 'OpenAPI — спецификация для описания REST API в формате YAML/JSON. Swagger — инструменты для работы со спецификацией (Swagger UI, Swagger Codegen, Swagger Editor). Статья объясняет, как описывать эндпоинты, модели, параметры, аутентификацию, генерировать клиентов и документацию, тестировать API через Swagger UI. Примеры интеграции с Spring Boot, FastAPI.', '34f86578-c009-4282-bcf6-299c3890daec', 167, 47, 4.8, now(), now()),
    (gen_random_uuid(), 'Linux командная строка: основные команды', 'Базовые команды Linux: навигация (ls, cd, pwd), работа с файлами (cp, mv, rm, touch, cat, less), права доступа (chmod, chown), процессы (ps, top, kill), сеть (ping, netstat, curl), поиск (find, grep), архивация (tar, gzip), текстовые редакторы (nano, vim). Статья с примерами для повседневной разработки и администрирования.', '34f86578-c009-4282-bcf6-299c3890daec', 234, 68, 4.8, now(), now()),
    (gen_random_uuid(), 'WebAssembly: запуск кода на других языках в браузере', 'WebAssembly (WASM) — бинарный формат инструкций для выполнения в браузере рядом с JavaScript. Статья объясняет, как компилировать C/C++/Rust/Go в .wasm, использовать из JS, интеграция с веб-API. Преимущества: производительность, повторное использование существующего кода. Пример: обработка изображений, игры, эмуляторы.', '34f86578-c009-4282-bcf6-299c3890daec', 76, 18, 4.5, now(), now()),
    (gen_random_uuid(), 'Монады в функциональном программировании (Option, Either, IO)', 'Монады — абстракция для композиции вычислений с контекстом. Option (Maybe) — обработка отсутствия значения. Either — обработка ошибок с информацией о причине. IO — отделение чистого кода от операций ввода-вывода. Статья объясняет функторы, монадические законы (bind, return), примеры на Scala, Haskell, Java (Optional), пояснения для Python-разработчиков.', '34f86578-c009-4282-bcf6-299c3890daec', 89, 22, 4.6, now(), now()),
    (gen_random_uuid(), 'Nginx: настройка веб-сервера и reverse-proxy', 'Nginx — высокопроизводительный веб-сервер и обратный прокси. Статья охватывает: базовая конфигурация (server, location, root, index), обслуживание статики, проксирование на бэкенд (proxy_pass), балансировка нагрузки (upstream), SSL/TLS (Let''s Encrypt), кеширование, ограничение запросов (rate limiting), логгирование. Примеры для Django, Node.js, статических сайтов.', '34f86578-c009-4282-bcf6-299c3890daec', 145, 41, 4.7, now(), now()),
    (gen_random_uuid(), 'Elasticsearch: поиск и аналитика больших данных', 'Elasticsearch — распределённая поисковая и аналитическая система на базе Lucene. Статья объясняет: индексы, документы (JSON), шардирование, репликация, Query DSL, полнотекстовый поиск, агрегации, Kibana для визуализации. Примеры: поиск по логам, каталогу товаров, метрикам. Сравнение с SQL (LIKE vs полнотекстовый поиск).', '34f86578-c009-4282-bcf6-299c3890daec', 112, 28, 4.7, now(), now()),
    (gen_random_uuid(), 'Архитектура чистой архитектуры (Clean Architecture) от Роберта Мартина', 'Чистая архитектура — подход с разделением на слои: Entities (бизнес-логика), Use Cases (интеракторы), Interface Adapters (контроллеры, презентеры), Frameworks & Drivers (БД, веб, UI). Принцип зависимости: зависимости идут внутрь, к бизнес-логике. Статья объясняет преимущества (тестируемость, независимость от деталей), пример структуры проекта на Java/Python.', '34f86578-c009-4282-bcf6-299c3890daec', 167, 44, 4.8, now(), now()),
    (gen_random_uuid(), 'Kafka: стриминговая платформа для событий', 'Apache Kafka — распределённая платформа для обработки потоков данных в реальном времени. Статья объясняет: топики (topics), партиции (partitions), продюсеры (producers), консьюмеры (consumers), группы потребителей (consumer groups), broker, ZooKeeper/KRaft. Примеры: сбор логов, аналитика кликов, CDC (Change Data Capture). Сравнение с RabbitMQ.', '34f86578-c009-4282-bcf6-299c3890daec', 134, 36, 4.7, now(), now()),
    (gen_random_uuid(), 'Методологии разработки: Agile, Scrum, Kanban', 'Методологии управления проектами. Agile — итеративная разработка с гибкостью. Scrum — роли (Product Owner, Scrum Master, команда), артефакты (бэклог, спринт, инкремент), события (планирование, ежедневки, ретроспектива). Kanban — визуализация потока (доска с колонками To Do, In Progress, Done), WIP лимиты. Статья поможет выбрать подход для команды.', '34f86578-c009-4282-bcf6-299c3890daec', 203, 59, 4.8, now(), now()),
    (gen_random_uuid(), 'Глубокое обучение: нейронные сети для начинающих', 'Введение в нейронные сети: перцептрон, слои (input, hidden, output), активационные функции (ReLU, sigmoid, tanh), прямое распространение (forward propagation), обратное распространение ошибки (backpropagation), градиентный спуск. Статья объясняет обучение на примере распознавания рукописных цифр (MNIST) с использованием TensorFlow/PyTorch. Минимум математики, больше интуиции.', '34f86578-c009-4282-bcf6-299c3890daec', 256, 72, 4.9, now(), now()),
    (gen_random_uuid(), 'Блочная верстка CSS: Flexbox и Grid', 'Современные CSS технологии для построения сеток. Flexbox — одномерная компоновка (основная и поперечная оси), свойства: display: flex, justify-content, align-items, flex-direction, flex-wrap. Grid — двухмерная компоновка (строки и колонки), свойства: grid-template-columns/rows, gap, grid-area. Статья с интерактивными примерами и типовыми паттернами.', '34f86578-c009-4282-bcf6-299c3890daec', 189, 53, 4.8, now(), now()),
    (gen_random_uuid(), 'Алгоритмы шифрования: симметричные и асимметричные', 'Криптография для защиты данных. Симметричное шифрование (AES, ChaCha20) — один ключ для шифрования и дешифрования. Асимметричное (RSA, ECC) — открытый и закрытый ключи. Статья объясняет хэширование (SHA-256), цифровые подписи, TLS/SSL. Примеры на Python (cryptography, hashlib). Понимание, где какой тип использовать.', '34f86578-c009-4282-bcf6-299c3890daec', 156, 43, 4.7, now(), now()),
    (gen_random_uuid(), 'Микросервисные паттерны: API Gateway, Service Discovery, Circuit Breaker', 'Паттерны для надёжных микросервисов. API Gateway — единая точка входа, маршрутизация. Service Discovery (Consul, Eureka) — динамическое обнаружение сервисов. Circuit Breaker (Resilience4j, Hystrix) — защита от каскадных отказов. Статья объясняет retry, timeout, bulkhead, rate limiter. Примеры реализации на Spring Cloud, Netflix OSS.', '34f86578-c009-4282-bcf6-299c3890daec', 134, 37, 4.7, now(), now())
INSERT INTO article (id, title, content, author_id, likes_count, comments_count, log_score, created_at, updated_at) VALUES
                                                                                                                        (gen_random_uuid(), 'Что такое алгоритм? Основные свойства алгоритмов', 'Алгоритм — это конечная последовательность шагов для решения задачи. Основные свойства: дискретность (разбиение на отдельные шаги), определённость (каждый шаг понятен исполнителю), результативность (должен давать результат), массовость (работает для всех задач из некоторого класса), конечность (завершается за конечное время). В статье рассматриваются примеры алгоритмов из повседневной жизни (приготовление чая, сборка мебели, поиск книги в библиотеке) и способы их записи: словесный, графический (блок-схемы), программный (код).', '34f86578-c009-4282-bcf6-299c3890daec', 56, 14, 4.6, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Блок-схемы: визуальное представление алгоритмов', 'Блок-схема — графический способ описания алгоритма с помощью геометрических фигур (блоков), соединённых стрелками. Основные блоки: начало/конец (овал), действие (прямоугольник), условие (ромб), ввод/вывод (параллелограмм), цикл (шестиугольник или прямоугольник с условием). Статья содержит правила построения блок-схем по ГОСТ, примеры для линейных, разветвляющихся и циклических алгоритмов, а также разбор типичных ошибок начинающих.', '34f86578-c009-4282-bcf6-299c3890daec', 78, 21, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Линейные алгоритмы: последовательность действий', 'Линейный алгоритм — действия выполняются строго одно за другим в порядке записи. Простейший тип алгоритмов. Пример: алгоритм вычисления площади прямоугольника (ввести длину и ширину, умножить их, вывести результат). Статья содержит 10 задач на линейные алгоритмы с решениями на Python и блок-схемами: вычисление выражений, перевод единиц измерения, обмен значений переменных, вычисление среднего арифметического, расчёт стоимости покупки со скидкой.', '34f86578-c009-4282-bcf6-299c3890daec', 92, 28, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Условный оператор if: ветвление в программах', 'Условный оператор позволяет выполнять разные действия в зависимости от условия. Полная форма: if (условие) { блок1 } else { блок2 }. Сокращённая: if (условие) { блок }. Сложные условия: and (и), or (или), not (не). Статья на примерах разбирает: проверку чётности числа, определение високосного года, сравнение трёх чисел, вычисление знака числа, проверку возраста для доступа к сайту. Вложенные условия и конструкция elif в Python.', '34f86578-c009-4282-bcf6-299c3890daec', 187, 52, 4.9, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Циклы: for и while', 'Циклы — многократное выполнение одного и того же блока команд. Цикл for (со счётчиком) используется когда известно количество повторений. Цикл while (с предусловием) — когда повторения зависят от условия. Статья объясняет: break (досрочный выход), continue (переход к следующей итерации), вложенные циклы. Реальные задачи: вывод таблицы умножения, вычисление факториала, поиск простых чисел, сумма цифр числа, игра «Угадай число».', '34f86578-c009-4282-bcf6-299c3890daec', 234, 67, 4.9, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Списки в Python: операции и методы', 'Список (list) — упорядоченная изменяемая коллекция элементов. Создание: [1, 2, 3]. Индексация (с 0) и срезы [start:stop:step]. Основные методы: append (добавить в конец), insert (вставить по индексу), remove (удалить по значению), pop (удалить по индексу), sort (сортировка), reverse (обратный порядок). Статья содержит примеры: инвентарь в игре, список дел, обработка оценок учеников, удаление дубликатов, поиск максимального элемента, разворот списка без встроенных функций.', '34f86578-c009-4282-bcf6-299c3890daec', 156, 43, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Строки: обработка текстовой информации', 'Строка (str) — неизменяемая последовательность символов. Конкатенация (+), дублирование (*), длина (len), срезы. Методы: lower/upper (регистр), strip (удаление пробелов), split/join (разделение/соединение), find/index (поиск подстроки), replace (замена), isdigit/isalpha (проверка содержимого). Задачи: проверка палиндрома, подсчёт гласных/согласных, шифр Цезаря, преобразование snake_case в camelCase, удаление лишних пробелов, форматирование ФИО.', '34f86578-c009-4282-bcf6-299c3890daec', 143, 39, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Словари: хранение данных по ключу', 'Словарь (dict) — неупорядоченная коллекция пар ключ-значение. Создание: {"имя": "Анна", "возраст": 15}. Доступ: dict[ключ] или dict.get(ключ). Добавление/изменение: dict[ключ] = значение. Удаление: del dict[ключ] или pop. Итерация по ключам, значениям, парам (items). Примеры: телефонная книга, переводчик (англо-русский словарь), подсчёт частоты слов в тексте, хранение информации о студентах, кэш результатов вычислений, конвертация двух списков в словарь.', '34f86578-c009-4282-bcf6-299c3890daec', 168, 47, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Функции: повторное использование кода', 'Функция — именованный блок кода, который можно вызывать многократно. Определение: def имя(параметры): тело. Возврат значения: return. Аргументы: позиционные, именованные, значения по умолчанию, произвольное количество (*args, **kwargs). Области видимости переменных (локальные, глобальные). Статья приводит примеры: функция для вычисления НОД, проверки простого числа, генерации паролей, конвертации температур, валидации email, факториала (рекурсия и итерация).', '34f86578-c009-4282-bcf6-299c3890daec', 212, 61, 4.9, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Рекурсия: функции, вызывающие себя', 'Рекурсия — когда функция вызывает саму себя. Обязательные компоненты: базовый случай (условие остановки) и рекурсивный шаг (вызов с изменёнными параметрами). Статья разбирает классические рекурсивные задачи: вычисление факториала (n! = n * (n-1)!), числа Фибоначчи (F(n) = F(n-1) + F(n-2)), обход папок, решение Ханойских башен, бинарный поиск, подсчёт глубины вложенности списков. Сравнение рекурсии и итерации, проблема переполнения стека, оптимизация с мемоизацией (lru_cache).', '34f86578-c009-4282-bcf6-299c3890daec', 98, 26, 4.6, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Сортировка пузырьком: простейший алгоритм сортировки', 'Сортировка пузырьком (bubble sort) — простой алгоритм, который многократно проходит по списку, сравнивая соседние элементы и меняя их местами, если они расположены не в правильном порядке. Асимптотика O(n²) в худшем случае. Статья содержит: визуализацию алгоритма, реализацию на Python с оптимизациями (флаг обмена, учёт конца отсортированного хвоста), сравнение с другими алгоритмами, практические задания: сортировка имён по алфавиту, сортировка учеников по росту, поиск медианы.', '34f86578-c009-4282-bcf6-299c3890daec', 87, 24, 4.5, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Бинарный поиск: эффективный поиск в отсортированном массиве', 'Бинарный (двоичный) поиск — алгоритм, который находит позицию элемента в отсортированном массиве, деля массив пополам на каждом шаге. Асимптотика O(log n) — очень быстро даже для больших массивов. Статья объясняет итеративную и рекурсивную реализации, граничные условия (левый/правый поиск), поиск вставки элемента, применение для решения уравнений, поиск корня числа. Сравнение с линейным поиском на примерах (поиск в телефонной книге из миллиона записей).', '34f86578-c009-4282-bcf6-299c3890daec', 134, 38, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Обработка исключений: try, except, finally', 'Исключения — ошибки, возникающие во время выполнения программы (деление на ноль, доступ по несуществующему индексу, открытие отсутствующего файла). Конструкция try-except перехватывает исключения и позволяет корректно их обработать. Статья объясняет: типы исключений (ValueError, TypeError, IndexError, KeyError, FileNotFoundError), блок else (выполняется если нет исключений), finally (выполняется всегда), создание своих исключений. Примеры: безопасное преобразование в число, повторный запрос ввода, логирование ошибок, закрытие файлов.', '34f86578-c009-4282-bcf6-299c3890daec', 145, 41, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Файловый ввод/вывод: чтение и запись файлов', 'Работа с файлами — сохранение данных между запусками программы. Открытие файла: open(путь, режим). Режимы: r (чтение), w (запись с перезаписью), a (дозапись), x (создание, ошибка если существует), b (бинарный режим). Методы: read, readline, readlines, write, writelines. Контекстный менеджер with (автоматическое закрытие). Практические задачи: подсчёт строк и слов в файле, копирование файла, запись результатов работы программы, сохранение настроек, ведение журнала (лог-файла), обработка CSV и JSON.', '34f86578-c009-4282-bcf6-299c3890daec', 121, 35, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Модули и библиотеки: расширение возможностей Python', 'Модуль — файл с Python-кодом, который можно импортировать. Стандартная библиотека содержит множество полезных модулей: math (математические функции), random (генерация случайных чисел), datetime (работа с датами), os (операционная система), sys (системные параметры), json (работа с JSON), csv (работа с CSV), re (регулярные выражения). Статья учит: импорт целиком (import math), импорт отдельных функций (from math import sqrt), импорт с псевдонимом (import numpy as np), установка сторонних библиотек через pip. Примеры: генерация случайного пароля, вычисление квадратного корня, работа с текущей датой.', '34f86578-c009-4282-bcf6-299c3890daec', 178, 51, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Простые числа: алгоритмы поиска и проверки', 'Простое число — натуральное число, которое делится только на 1 и на себя. Алгоритмы: проверка делителями до √n (эффективно), решето Эратосфена (для нахождения всех простых до N). Статья содержит: реализацию проверки простоты числа, оптимизации (отсев чётных, шаг 6k±1), нахождение всех простых до 1 миллиона через решето Эратосфена с визуализацией, разложение на простые множители, поиск простых чисел-близнецов, проверка числа Мерсенна. Примеры кода с объяснением сложности.', '34f86578-c009-4282-bcf6-299c3890daec', 109, 30, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Системы счисления: перевод между основаниями', 'Система счисления — способ записи чисел. Позиционные: двоичная (2), восьмеричная (8), десятичная (10), шестнадцатеричная (16). Алгоритмы перевода: из любой системы в десятичную (через разряды), из десятичной в любую (делением на основание). Статья содержит: таблицы соответствия цифр, перевод целых и дробных чисел, арифметика в разных системах, применение в информатике (битовые операции, цвета RGB, MAC-адреса, IP-адреса). Реализация переводчика систем счисления на Python с использованием встроенных функций bin(), oct(), hex().', '34f86578-c009-4282-bcf6-299c3890daec', 198, 58, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Битовые операции: работа на уровне битов', 'Битовые операции — манипуляции с отдельными битами числа. AND (&), OR (|), XOR (^), NOT (~), сдвиги влево (<<) и вправо (>>). Применение: проверка чётности (x & 1), установка/сброс/инвертирование бита, умножение/деление на степень двойки, эффективное хранение флагов (битовые маски), проверка степени двойки, подсчёт единичных битов (popcount). Статья объясняет каждую операцию на примерах, показывает реализацию на Python, разбирает задачи: упаковка четырёх байт в int, шифрование XOR, переключение бита, циклический сдвиг.', '34f86578-c009-4282-bcf6-299c3890daec', 87, 23, 4.6, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Отладка программ: инструменты и техники', 'Отладка (debugging) — процесс поиска и исправления ошибок в программе. Виды ошибок: синтаксические (не запускается), логические (работает неверно), времени выполнения (падает при определённых условиях). Инструменты: print-логирование, assert, отладчик pdb (breakpoint(), step, continue, watch), IDE-отладчики (PyCharm, VS Code) с точками останова. Техники: метод принта, бинарный поиск ошибки, воспроизведение минимального примера, чтение стека вызовов, проверка крайних случаев. Статья содержит практические кейсы и чеклист действий при ошибке.', '34f86578-c009-4282-bcf6-299c3890daec', 112, 32, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Черепашья графика: основы программирования через рисование', 'Черепашья графика (turtle) — простой способ обучения программированию через управление "черепашкой", которая рисует на экране. Основные команды: forward/backward (движение), left/right (поворот), penup/pendown (поднять/опустить перо), color (цвет), pensize (толщина). Статья содержит примеры: квадрат, треугольник, круг (через многоугольник), звёзды, снежинки, спирали, фракталы (дерево, треугольник Серпинского), анимация движения. Подходит для начинающих: визуальный результат, отработка циклов, функций, рекурсии.', '34f86578-c009-4282-bcf6-299c3890daec', 134, 39, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Компьютерные сети: основы и терминология', 'Компьютерная сеть — объединение устройств для обмена данными. Классификация: LAN (локальная), WAN (глобальная), MAN (городская), PAN (персональная). Топологии: шина, звезда, кольцо, полносвязная, ячеистая. Оборудование: сетевая карта, свитч, маршрутизатор, модем, точка доступа. Среда передачи: витая пара, оптоволокно, радиоканал. Статья объясняет IP-адресацию (IPv4, IPv6), порты (0-65535), DNS (доменные имена), NAT (преобразование адресов). Примеры: домашняя сеть, офисная сеть, интернет.', '34f86578-c009-4282-bcf6-299c3890daec', 145, 42, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Модель OSI: 7 уровней сетевого взаимодействия', 'Модель OSI (Open Systems Interconnection) — эталонная модель, описывающая взаимодействие сетевых протоколов. 7 уровней (снизу вверх): 1) Физический — кабели, сигналы; 2) Канальный — MAC-адреса, коммутаторы; 3) Сетевой — IP-адреса, маршрутизация; 4) Транспортный — TCP/UDP, порты; 5) Сеансовый — установка сессий; 6) Представления — шифрование, сжатие; 7) Прикладной — HTTP, FTP, SMTP, DNS. Статья объясняет каждую функцию, принцип инкапсуляции (данные "оборачиваются" заголовками при движении вниз по уровням), приводит аналогии с почтой и путешествиями. Сравнение с моделью TCP/IP (4 уровня).', '34f86578-c009-4282-bcf6-299c3890daec', 167, 48, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Протокол HTTP: как работают веб-сайты', 'HTTP (HyperText Transfer Protocol) — протокол передачи гипертекста, основа веба. Методы: GET (получить данные), POST (отправить данные), PUT (обновить), DELETE (удалить), PATCH (частичное обновление). Статус-коды: 1xx (информационные), 2xx (успех — 200 OK), 3xx (перенаправление — 301, 302), 4xx (ошибка клиента — 404 Not Found, 403 Forbidden), 5xx (ошибка сервера — 500). Заголовки (Content-Type, Cookie, Authorization). Структура запроса и ответа. HTTPS — зашифрованная версия с TLS/SSL. Статья разбирает как браузер загружает страницу, что такое REST API, примеры запросов через curl.', '34f86578-c009-4282-bcf6-299c3890daec', 234, 69, 4.9, now(), now()),
                                                                                                                        (gen_random_uuid(), 'IP-адресация и маски подсетей', 'IP-адрес — уникальный идентификатор устройства в сети. IPv4 — 32 бита (4 числа от 0 до 255, например 192.168.1.1). Маска подсети определяет, какая часть адреса относится к сети, какая — к хосту. CIDR-нотация: /24 означает 24 бита сети. Классы адресов (A, B, C, D, E). Специальные адреса: loopback (127.0.0.1 — localhost), частные сети (192.168.x.x, 10.x.x.x, 172.16.x.x), широковещательный (255.255.255.255). Статья учит: вычисление адреса сети, broadcast-адреса, диапазона хостов, деление сети на подсети, перевод в двоичную систему. Примеры для 9 класса без сложной математики.', '34f86578-c009-4282-bcf6-299c3890daec', 156, 44, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'DNS: как браузер находит сайт', 'DNS (Domain Name System) — система, преобразующая доменные имена (google.com, youtube.com) в IP-адреса (142.250.185.46). Иерархическая структура: корневые серверы, TLD-серверы (.com, .ru, .org), авторитативные серверы. Типы DNS-записей: A (IPv4), AAAA (IPv6), CNAME (алиас), MX (почта), TXT (текст, например для проверки домена). Резолвинг: браузер → кэш ОС → кэш роутера → DNS-сервер провайдера → рекурсивный запрос. Статья объясняет DNS-запросы (recursive, iterative), популярные публичные DNS (Google 8.8.8.8, Cloudflare 1.1.1.1), кэширование, понятие TTL (Time To Live).', '34f86578-c009-4282-bcf6-299c3890daec', 189, 54, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Базы данных: таблицы, ключи, связи', 'База данных (БД) — организованное хранилище данных. Реляционные БД (SQL) хранят данные в таблицах. Таблица состоит из строк (записи) и столбцов (поля). Первичный ключ (PRIMARY KEY) — уникальный идентификатор строки. Внешний ключ (FOREIGN KEY) — ссылка на первичный ключ другой таблицы. Типы связей: один-к-одному (1:1), один-ко-многим (1:N), многие-ко-многим (M:N, реализуется через промежуточную таблицу). Статья на примере "Ученики-Классы" объясняет нормализацию (избегание дублирования), индексы (ускорение поиска).', '34f86578-c009-4282-bcf6-299c3890daec', 178, 51, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Типы данных в SQL: INTEGER, VARCHAR, DATE и другие', 'SQL поддерживает различные типы данных для хранения разной информации. Числовые: INTEGER (целые), BIGINT (большие целые), DECIMAL/NUMERIC (фиксированная точность), FLOAT/REAL (плавающая точка). Строковые: CHAR (фиксированная длина), VARCHAR (переменная длина), TEXT (большой текст). Дата/время: DATE (только дата), TIME (время), TIMESTAMP (дата+время). Логический: BOOLEAN (TRUE/FALSE). Другие: UUID (универсальный идентификатор), JSON/JSONB (хранение JSON), ENUM (перечисление). Статья помогает выбрать правильный тип для поля: возраст — INTEGER, имя — VARCHAR(255), дата рождения — DATE, цена — DECIMAL(10,2), описание — TEXT.', '34f86578-c009-4282-bcf6-299c3890daec', 123, 36, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'SQL запросы: SELECT, WHERE, ORDER BY', 'SELECT — самый частый SQL-запрос для получения данных. Синтаксис: SELECT столбцы FROM таблица WHERE условие ORDER BY сортировка. * означает все столбцы. WHERE фильтрует строки: сравнения (=, <>, >, <, >=, <=), логические операторы (AND, OR, NOT), BETWEEN (в диапазоне), IN (в списке), LIKE (по шаблону, % — любая последовательность, _ — один символ), IS NULL (проверка на пустое значение). ORDER BY сортирует по одному или нескольким столбцам (ASC — по возрастанию, DESC — по убыванию). LIMIT ограничивает количество строк. Статья содержит 15 примеров запросов к учебной БД "Школа".', '34f86578-c009-4282-bcf6-299c3890daec', 234, 68, 4.9, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Агрегатные функции: COUNT, SUM, AVG, MIN, MAX', 'Агрегатные функции выполняют вычисления над группой строк и возвращают одно значение. COUNT(*) — количество строк, COUNT(столбец) — количество ненулевых значений. SUM — сумма, AVG — среднее арифметическое, MIN — минимум, MAX — максимум. Используются с GROUP BY для группировки данных. HAVING — фильтрация после группировки (аналог WHERE для агрегатов). Примеры: общее количество учеников, средний балл по классам, максимальная зарплата по отделам, сумма продаж по месяцам, количество заказов у каждого клиента. Важное отличие WHERE (фильтрация строк до группировки) от HAVING (после группировки).', '34f86578-c009-4282-bcf6-299c3890daec', 201, 59, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'JOIN: объединение таблиц в SQL', 'JOIN — объединение данных из нескольких таблиц по связям. INNER JOIN — только строки с совпадениями в обеих таблицах. LEFT JOIN — все строки из левой таблицы, NULL для правой если нет совпадения. RIGHT JOIN — наоборот. FULL OUTER JOIN — все строки из обеих таблиц. CROSS JOIN — декартово произведение (все пары). Пример: таблицы Ученики (id, имя, класс_id) и Классы (id, название, учитель). JOIN выводит учеников с названием их класса и учителем. Статья разбирает каждый тип на понятных примерах, показывает разницу на диаграммах Венна, объясняет объединение нескольких таблиц, алиасы (AS) для краткости.', '34f86578-c009-4282-bcf6-299c3890daec', 267, 78, 4.9, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Индексы в базах данных: ускорение запросов', 'Индекс — структура данных, ускоряющая поиск строк по определённому столбцу (аналогично оглавлению в книге). B-Tree — самый распространённый тип индекса (эффективен для равенства и диапазонов). Уникальный индекс — обеспечивает уникальность значений. Составной индекс — по нескольким столбцам. Статья объясняет: создание индекса (CREATE INDEX), удаление, когда индексы полезны (WHERE, JOIN, ORDER BY, большие таблицы), когда вредны (частые INSERT/UPDATE/DELETE, маленькие таблицы). Понятие покрывающего индекса. Анализ плана запроса (EXPLAIN) для проверки использования индексов. Практические советы по индексированию.', '34f86578-c009-4282-bcf6-299c3890daec', 145, 42, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Транзакции: ACID и целостность данных', 'Транзакция — группа операций, которые выполняются как единое целое: либо все успешно, либо ни одна. ACID — свойства транзакций: Atomicity (атомарность — всё или ничего), Consistency (согласованность — база остаётся в корректном состоянии), Isolation (изоляция — параллельные транзакции не мешают друг другу), Durability (долговечность — зафиксированные данные сохраняются при сбоях). SQL команды: BEGIN (начать транзакцию), COMMIT (зафиксировать), ROLLBACK (откатить). Статья на примере банковского перевода: списать с одного счёта и зачислить на другой. Уровни изоляции (READ UNCOMMITTED, READ COMMITTED, REPEATABLE READ, SERIALIZABLE) и их влияние на производительность и целостность.', '34f86578-c009-4282-bcf6-299c3890daec', 189, 53, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Нормализация: 1, 2, 3 нормальные формы', 'Нормализация — процесс проектирования БД для устранения избыточности и аномалий. 1НФ: каждое поле содержит атомарное (неделимое) значение, нет повторяющихся групп. 2НФ: выполнена 1НФ и все неключевые поля зависят от полного первичного ключа (устранение частичной зависимости). 3НФ: выполнена 2НФ и все неключевые поля зависят только от первичного ключа (устранение транзитивной зависимости). Статья на примере таблицы "Заказы" (клиент, город, товар, цена) объясняет, как разделить на три таблицы: Клиенты, Товары, Заказы, и почему это лучше. Примеры аномалий: вставки (не можем добавить клиента без заказа), обновления (менять город в 100 местах), удаления (теряем клиента при удалении заказа).', '34f86578-c009-4282-bcf6-299c3890daec', 156, 45, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Хэш-функции: от паролей до контрольных сумм', 'Хэш-функция — преобразование входных данных произвольного размера в строку фиксированной длины (хэш, дайджест). Свойства: односторонность (нельзя восстановить исходные данные по хэшу), детерминированность (одинаковый вход = одинаковый выход), лавинный эффект (малое изменение входа сильно меняет выход). MD5, SHA-1, SHA-256 — популярные алгоритмы. Применение: хранение паролей (хэш + соль), проверка целостности файлов (контрольные суммы), цифровые подписи, поиск дубликатов, хэш-таблицы (словари). Статья содержит реализацию простой хэш-функции, объясняет коллизии (два разных входа дают одинаковый хэш), атаку "дней рождения".', '34f86578-c009-4282-bcf6-299c3890daec', 134, 38, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Симметричное и асимметричное шифрование', 'Шифрование — превращение данных в нечитаемый вид (шифротекст), расшифрование — обратное преобразование. Симметричное (AES, ChaCha20): один ключ для шифрования и расшифрования. Плюс: быстро, минус: проблема передачи ключа. Асимметричное (RSA, ECC): два ключа — открытый (шифрование) и закрытый (расшифрование). Плюс: безопасная передача, минус: медленно. Статья объясняет: пример с сейфом и почтовым ящиком, гибридное шифрование (обмениваются через асимметричное, данные — через симметричное), применение в HTTPS/TLS, электронной почте (PGP), цифровых подписях. Реализация шифрования на Python (cryptography, hashlib).', '34f86578-c009-4282-bcf6-299c3890daec', 167, 47, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Компьютерная графика: пиксели, векторы, цвета', 'Компьютерная графика делится на растровую (состоит из пикселей, каждый хранит цвет) и векторную (хранит математические формулы линий и фигур). Цветовые модели: RGB (красный, зелёный, синий — для мониторов, каждый от 0 до 255), CMYK (голубой, пурпурный, жёлтый, чёрный — для печати), HSV (оттенок, насыщенность, яркость). Глубина цвета: 1 бит (ч/б), 8 бит (256 цветов), 24 бита (16.7 млн цветов — True Color). Разрешение (ppi, dpi) — количество пикселей на дюйм. Форматы: JPEG (сжатие с потерями), PNG (прозрачность), GIF (анимация), SVG (векторный). Статья объясняет, как кодировать цвета в вебе (#RRGGBB), примеры на Python (PIL/Pillow).', '34f86578-c009-4282-bcf6-299c3890daec', 123, 35, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Кодирование текста: ASCII, Unicode, UTF-8', 'Кодировка — правило, сопоставляющее символам числа (коды). ASCII (7 бит, 0-127): английские буквы, цифры, знаки препинания — основа основ. Расширенный ASCII (8 бит, 128-255) — национальные символы, но разные в разных кодировках (Windows-1251 для русского). Unicode (Юникод) — единая таблица для всех языков мира, содержит более 140 тысяч символов. UTF-8 — способ хранения Unicode: символы ASCII занимают 1 байт (обратно совместима), русские буквы — 2 байта, эмодзи — 4 байта. Статья объясняет, почему появляются "кракозябры" (попытка прочитать текст в другой кодировке), показывает коды символов в Python (ord, chr).', '34f86578-c009-4282-bcf6-299c3890daec', 178, 52, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Алгоритмы сжатия данных: без потерь и с потерями', 'Сжатие — уменьшение объёма данных. Без потерь (zip, gzip, PNG, FLAC): исходные данные можно восстановить полностью. Алгоритмы: RLE (повторяющиеся символы заменяются парой символ-количество), Хаффман (частые символы — короткие коды), LZ77 (ссылки на предыдущие вхождения). С потерями (JPEG, MP3, MPEG): удаляется информация, незаметная для человека (высокие частоты в звуке, мелкие детали в изображении). Статья объясняет коэффициент сжатия, пример RLE на Python ("AAAABBBCC" → "4A3B2C"), сжатие изображений через уменьшение цветов или преобразование Фурье (на пальцах). Почему zip не сжимает уже сжатые файлы (jpg, mp4).', '34f86578-c009-4282-bcf6-299c3890daec', 145, 41, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Регулярные выражения: поиск по шаблону', 'Регулярные выражения (regex, regexp) — мощный язык для поиска и замены текста по шаблону. Метасимволы: . (любой символ), \d (цифра), \w (буква/цифра/_), \s (пробел), ^ (начало строки), $ (конец). Квантификаторы: * (0 или более), + (1 или более), ? (0 или 1), {n} (ровно n), {n,m} (от n до m). Символьные классы: [a-z], [0-9], [а-яё]. Группы: ( ) — захват группы для извлечения подстроки. Примеры: проверка email (\w+@\w+\.\w+), номера телефона (\+\d{1,3}\(\d{3}\)\d{7}), поиска всех ссылок в HTML, извлечения дат ((\d{2})\.(\d{2})\.(\d{4})). Статья содержит 10 задач с решениями на Python (re модуль: match, search, findall, sub).', '34f86578-c009-4282-bcf6-299c3890daec', 189, 55, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Web-скрапинг: сбор данных с сайтов', 'Веб-скрапинг (парсинг) — автоматический сбор данных с веб-страниц. Инструменты: requests (загрузка страницы), BeautifulSoup (разбор HTML), Selenium (для динамических страниц с JavaScript). Основные этапы: получить HTML, найти нужные элементы (по тегу, классу, id, CSS-селектору, XPath), извлечь текст/атрибуты, сохранить результат (CSV, JSON, база данных). Статья разбирает пример: парсинг заголовков новостей с сайта, цен товаров, таблиц с погодой. Правила этики: robots.txt (уважать запреты), задержки между запросами (time.sleep), использование User-Agent. Юридические аспекты: парсинг публичных данных обычно разрешён, авторизованных — нет.', '34f86578-c009-4282-bcf6-299c3890daec', 156, 44, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'API: как программы общаются друг с другом', 'API (Application Programming Interface) — набор правил и инструментов для взаимодействия программ. Веб-API (REST, GraphQL) — через HTTP запросы. Чаще всего данные передаются в формате JSON (JavaScript Object Notation) — текст, похожий на словари Python. Статья объясняет: как работать с публичными API (погода, курсы валют, погода, новости, Telegram бот), ключи API (токены для аутентификации), ограничения (rate limiting). Пример: отправка GET запроса через requests, разбор JSON ответа, извлечение нужной информации. Создание простого API через Flask (разные маршруты, возврат JSON, обработка параметров в URL).', '34f86578-c009-4282-bcf6-299c3890daec', 234, 67, 4.9, now(), now()),
                                                                                                                        (gen_random_uuid(), 'JSON: формат обмена данными', 'JSON (JavaScript Object Notation) — текстовый формат для хранения и передачи данных. Легко читается человеком и легко парсится программами. Структуры: объект { "ключ": "значение" } (аналог словаря Python), массив [ "элемент1", "элемент2" ] (аналог списка). Типы данных: строки (в двойных кавычках), числа, булевы (true/false), null (пусто), объекты, массивы. Статья объясняет: пример JSON (информация о книге, студенте, заказе), сравнение с XML (JSON проще и легче). Работа с JSON в Python: json.dumps (Python → JSON), json.loads (JSON → Python), чтение/запись файлов (json.dump, json.load). Пример: сохранение настроек в config.json, обмен данными между клиентом и сервером.', '34f86578-c009-4282-bcf6-299c3890daec', 145, 42, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Алгоритмы сортировки: сравнение сложности (Big O notation)', 'Big O notation — способ оценки времени работы алгоритма в зависимости от размера входных данных. O(1) — константное время (доступ по индексу). O(log n) — логарифмическое (бинарный поиск). O(n) — линейное (простой поиск). O(n log n) — линейно-логарифмическое (быстрая сортировка, сортировка слиянием). O(n²) — квадратичное (пузырьковая, вставками в худшем случае). Статья сравнивает сортировки: пузырёк (O(n²) — медленно), быстрая (O(n log n) в среднем — быстро), слиянием (O(n log n) стабильно), подсчётом (O(n) для целых чисел). Таблица времени для разных n: для 1 млн элементов O(n²) — 10^12 операций (> 1 часа), O(n log n) — 20 млн операций (< 1 секунды).', '34f86578-c009-4282-bcf6-299c3890daec', 178, 50, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Рекурсия и итерация: сравнение и выбор', 'Рекурсия (функция вызывает саму себя) и итерация (циклы) — два способа повторения. Рекурсия красивее и понятнее для задач с древовидной структурой (обход папок, вычисление факториала, Ханойские башни). Итерация быстрее (нет накладных расходов на вызов функций) и безопаснее (нет риска переполнения стека при глубокой рекурсии). Статья показывает одну задачу двумя способами: вычисление факториала, чисел Фибоначчи (рекурсия O(2^n) против итерации O(n)), бинарный поиск, обход дерева. Рекурсия с мемоизацией (кэширование результатов) для Фибоначчи даёт O(n) — лучший из двух миров. Правило: если глубина рекурсии превышает 1000 — лучше итерация (лимит Python).', '34f86578-c009-4282-bcf6-299c3890daec', 109, 31, 4.6, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Стек и очередь: структуры данных в программировании', 'Стек (LIFO — Last In, First Out) — как стопка тарелок: последний положил — первый взял. Операции: push (добавить), pop (удалить последний). Применение: проверка скобок (соответствие [ { ( ) } ]), отмена действий (Ctrl+Z), обход графов в глубину (DFS). Очередь (FIFO — First In, First Out) — как очередь в магазине: первый пришёл — первый обслужен. Операции: enqueue (добавить в конец), dequeue (удалить из начала). Применение: задачи планировщика (печать документов, обработка заявок), обход графов в ширину (BFS), буфер сообщений. Статья содержит реализации на Python (список как стек, deque из collections как очередь).', '34f86578-c009-4282-bcf6-299c3890daec', 134, 38, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Динамическое программирование: оптимальные решения', 'Динамическое программирование (ДП) — метод решения задач путём разбиения на подзадачи и сохранения их результатов (мемоизация). Классические задачи: числа Фибоначчи (снизу вверх или сверху вниз с кэшем), задача о рюкзаке (как выбрать предметы максимальной цены при ограничении веса), поиск наибольшей общей подпоследовательности (для сравнения текстов), задача о лестнице (сколькими способами подняться на n-ступенек шагами 1 и 2), нахождение максимальной суммы подмассива (алгоритм Кадане). Статья объясняет принцип "решай подзадачи и запоминай", приводит таблицы ДП, показывает наивные рекурсивные решения и их оптимизацию.', '34f86578-c009-4282-bcf6-299c3890daec', 167, 46, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Жадные алгоритмы: простое решение для сложных задач', 'Жадные алгоритмы — на каждом шаге выбирают локально лучшее решение, надеясь получить глобально оптимальное. Иногда это работает (задача о минимальном количестве монет для выдачи сдачи: выдавать самые крупные), иногда нет (задача о рюкзаке — если брать самые ценные, можно пропустить комбинацию более ценных лёгких предметов). Задачи, где жадность работает: выбор задач (активностей) на одну аудиторию (брать самую раннезаканчивающуюся), построение минимального остовного дерева (алгоритмы Крускала и Прима), коды Хаффмана (оптимальное сжатие), Дейкстра (поиск кратчайшего пути в графе с неотрицательными весами). Статья объясняет принципы и ограничения.', '34f86578-c009-4282-bcf6-299c3890daec', 145, 40, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Графы: вершины, рёбра, обходы', 'Граф — множество вершин (узлов), соединённых рёбрами. Ориентированные (со стрелками, направление важно) и неориентированные (без стрелок). Взвешенные (на рёбрах есть числа — длины, цены) и невзвешенные. Способы хранения: матрица смежности (таблица n×n), список смежности (для каждой вершины — список соседей). Обходы: BFS (поиск в ширину, через очередь) — кратчайший путь в невзвешенном графе. DFS (поиск в глубину, через стек/рекурсию) — проверка связности, поиск цикла. Статья содержит примеры: карта метро (граф станций), друзья в соцсети (граф пользователей), поиск пути между городами, построение лабиринта.', '34f86578-c009-4282-bcf6-299c3890daec', 189, 54, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Компьютерные вирусы и антивирусная защита', 'Вредоносное ПО (малварь): вирусы (заражают файлы), черви (распространяются по сети), трояны (маскируются под полезные программы), шпионы (собирают данные), шифровальщики (требуют выкуп), руткиты (скрывают своё присутствие). Пути заражения: фишинговые письма, взломанные сайты, заражённые флешки, нелегальное ПО. Методы защиты: антивирусы (сигнатурный анализ — поиск известных вредоносных участков кода, эвристический — обнаружение подозрительного поведения), фаерволы (блокировка сетевых атак), регулярные обновления (закрытие уязвимостей). Статья даёт советы по безопасности: не открывать подозрительные вложения, использовать сложные пароли и двухфакторную аутентификацию, делать резервные копии, не подключать незнакомые флешки.', '34f86578-c009-4282-bcf6-299c3890daec', 234, 68, 4.8, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Open Source: свободное программное обеспечение', 'Open Source (открытый исходный код) — программы, чей код доступен для изучения, использования, изменения и распространения. Лицензии: GPL (производные работы тоже должны быть открытыми), MIT (самая свободная, можно делать закрытые коммерческие продукты), Apache (с защитой от патентных исков), BSD. Примеры: Linux (операционная система), Python (язык), Firefox (браузер), WordPress (CMS), Blender (3D-моделирование). Преимущества: безопасность (код проверяют тысячи людей), бесплатность, гибкость. Как участвовать: найти проект на GitHub, исправить ошибку, перевести документацию, добавить функцию. Статья объясняет культуру Open Source и платформы (GitHub, GitLab, SourceForge).', '34f86578-c009-4282-bcf6-299c3890daec', 156, 43, 4.7, now(), now()),
                                                                                                                        (gen_random_uuid(), 'Карьера в IT: профессии и навыки', 'IT-сфера предлагает множество профессий: разработчик (frontend — интерфейсы, backend — серверная логика, mobile — приложения, fullstack — всё вместе), тестировщик (QA — проверяет, чтобы всё работало, автоматизирует тесты), DevOps (развёртывание, мониторинг, инфраструктура), аналитик (сбор требований, анализ данных), Data Scientist (машинное обучение, анализ больших данных), системный администратор (настройка серверов и сетей), продакт-менеджер (управляет развитием продукта), дизайнер (UI/UX). Необходимые навыки: логическое мышление, знание английского (техническая документация), умение гуглить, работать в команде. Пути обучения: курсы, университет, самообразование (книги, YouTube, документация).', '34f86578-c009-4282-bcf6-299c3890daec', 345, 101, 4.9, now(), now())
